corrected_code:
@router.post("/notifications/channels/{channel_name}/broadcast")
async def broadcast_channel_message(
    channel_name: str,
    payload: BroadcastMessagePayload,
    redis: Redis = Depends(get_redis_client),
    current_user: User = Depends(get_current_user)
):
    if channel_name not in current_user.authorized_broadcast_channels and not current_user.is_system_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to broadcast on this channel")
    channel_key = f"events:{channel_name}"
    await redis.publish(channel_key, payload.model_dump_json())
    return {"dispatched": True, "channel": channel_name}
